{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    required = ("nodes", "core_distance", "distances")
    if any(key not in case for key in required):
        raise ValueError("missing required field")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]
    if not isinstance(nodes, list) or not isinstance(core_distance, dict) or not isinstance(distances, list):
        raise ValueError("invalid field type")
    if any(not isinstance(node, str) for node in nodes) or len(set(nodes)) != len(nodes):
        raise ValueError("nodes must be unique strings")
    node_set = set(nodes)
    if set(core_distance) != node_set:
        raise ValueError("core_distance keys must match nodes")

    def number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            raise ValueError(name + " must be a finite number")
        if value < 0:
            raise ValueError(name + " must be nonnegative")
        return value

    for node in nodes:
        number(core_distance[node], "core distance")

    edges = []
    seen_pairs = set()
    for position, entry in enumerate(distances):
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("each distance must contain two endpoints and a weight")
        left, right, distance = entry
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("invalid distance endpoint")
        distance = number(distance, "distance")
        first, second = (left, right) if left < right else (right, left)
        pair = (first, second)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance")
        seen_pairs.add(pair)
        weight = max(core_distance[first], core_distance[second], distance)
        edges.append((weight, first, second, position))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    selected = []
    total_weight = 0
    for weight, left, right, position in sorted(edges, key=lambda edge: (edge[0], edge[1], edge[2], edge[3])):
        if union(left, right):
            selected.append([left, right, weight])
            total_weight += weight
            if len(selected) == len(nodes) - 1:
                break

    if len(nodes) > 0 and len(selected) != len(nodes) - 1:
        raise ValueError("input graph is disconnected")
    return {"mst_edges": selected, "total_weight": total_weight}
"}
